L_FFB4:
	std	OC2next
L_FFB6:
	rti
SchedInj:
	pshb		; schedule the end of an injector pulse: OC1next = FRC + D (+ $22) [ROM:$FFB7-$FFE0] LIKELY
	ldab	StartCount
	cmpb	#$02
	ldab	FuelCut
	pulb
	bcc	L_FFED
	bne	L_FFED
	pshb
	sei
	ldab	PORT2
	bitb	#$02
	pulb
	bne	L_FFD0
	addd	OC1next
	bra	L_FFD4
L_FFD0:
	addd	InjDeadTime
	addd	FRCH
L_FFD4:
	subd	FRCH
	bpl	L_FFDB
	ldd	#$7FFF
L_FFDB:
	addd	FRCH
	addd	#$0022
	std	OC1next
	ldd	FRCH
	addd	#$0010
	std	OCRH
	ldaa	#$08
	staa	TCSR
L_FFED:
	rts
; $FFEE: checksum balance word; then SCI, TOF, OCF, ICF, IRQ1, SWI, NMI, RES
Vectors:
	dw	$523D,Reset,Reset,IRQ_OCF
	dw	IRQ_ICF,Reset,Reset,Reset
	dw	Reset

	end
